@Test
    public void testgcrma() {
        ScaleType s = QuantitationTypeParameterGuesser.guessScaleType( "VALUE", "gcRMA-calculated Signal intensity" );
        assertEquals( "got " + s, ScaleType.LOG2, s );
    }

